#!/usr/bin/env python3
"""Classify a catalog-only MoniKey schema inventory. No database connection here."""

from __future__ import annotations

import argparse
import hashlib
import json
import re
import sys
from datetime import datetime, timezone
from pathlib import Path

# These exact PostgreSQL 17 signatures are generated by the disposable fixture
# test from the canonical migrations. Any non-matching definition fails closed.
EXPECTED_SIGNATURES = {
    "002": "600204c45aaa0fee58a3cb3d9eb659d942bdcf6b87c76b706ae5b954fe9715ca",
    "004": "d93420745b7880c70e87f34f7c11ef8089878adcbfe8c00dc43a825eaca90dba",
    "005": "b7e231500ac5bdc7abe810692a3cfcec2524b5372966a9a92c5b265e2352f8b9",
    "006": "66b5c365af10efeaaeabe29ff31a9764a2b1740ba927891808d4e4015da97da6",
}


def signature_for(migration: str, tables: dict) -> str:
    def selected(table_name: str, columns: set[str] | None = None,
                 constraints: set[str] | None = None, indexes: set[str] | None = None,
                 comments: set[str] | None = None) -> dict:
        table = tables.get(table_name, {})
        return {
            "columns": {k: v for k, v in table.get("columns", {}).items() if columns is None or k in columns},
            "constraints": {k: v for k, v in table.get("constraints", {}).items() if constraints is None or k in constraints},
            "indexes": {k: v for k, v in table.get("indexes", {}).items() if indexes is None or k in indexes},
            "comments": {k: v for k, v in table.get("comments", {}).items() if comments is None or k in comments},
        }
    if migration == "002":
        data = {"account_transfers": selected("account_transfers")}
    elif migration == "004":
        data = {"accounts": selected("accounts", {"card_product_id"}, {
            "accounts_card_product_id_format", "accounts_card_product_id_not_cash"})}
    elif migration == "005":
        data = {
            "categories": selected("categories", {"default_kakeibo_envelope"}, {
                "categories_default_kakeibo_envelope_allowed", "categories_default_kakeibo_envelope_expense_only"}),
            "transactions": selected("transactions", {"kakeibo_envelope"},
                {"transactions_kakeibo_envelope_allowed"}, {"idx_transactions_kakeibo_date_envelope"}),
            "kakeibo_month_plans": selected("kakeibo_month_plans",
                {k for k in tables.get("kakeibo_month_plans", {}).get("columns", {}) if k != "plan_presence"},
                {k for k in tables.get("kakeibo_month_plans", {}).get("constraints", {}) if k != "kakeibo_month_plans_plan_presence_check"},
                comments=set()),
            "kakeibo_weekly_reviews": selected("kakeibo_weekly_reviews"),
        }
    elif migration == "006":
        data = {"kakeibo_month_plans": selected("kakeibo_month_plans", {"plan_presence"},
            {"kakeibo_month_plans_plan_presence_check"}, comments={"plan_presence"})}
    else:
        raise ValueError(f"no signature for migration {migration}")
    canonical = json.dumps(data, sort_keys=True, separators=(",", ":"), ensure_ascii=True)
    return hashlib.sha256(canonical.encode("utf-8")).hexdigest()


def _column(table: dict, name: str, type_name: str, nullable: bool) -> bool:
    value = table.get("columns", {}).get(name)
    return value == {"type": type_name, "nullable": nullable}


def _constraint(table: dict, name: str, kind: str, fragments: tuple[str, ...]) -> bool:
    value = table.get("constraints", {}).get(name)
    if not value or value.get("type") != kind:
        return False
    definition = " ".join(value.get("definition", "").lower().split())
    return all(fragment in definition for fragment in fragments)


def _index(table: dict, name: str, fragments: tuple[str, ...]) -> bool:
    value = table.get("indexes", {}).get(name)
    definition = " ".join((value or "").lower().split())
    return bool(value) and all(fragment in definition for fragment in fragments)


def _objects(inventory: dict) -> dict:
    return inventory.get("tables", {})


def _classify_002(tables: dict) -> tuple[str, list[str]]:
    name = "account_transfers"
    accounts = tables.get("accounts")
    if not accounts or not _column(accounts, "id", "integer", False):
        return "UNKNOWN", ["accounts prior schema is not established"]
    table = tables.get(name)
    if not table:
        if "account_transfers" in tables.get("__relation_kinds__", {}):
            return "PARTIAL", ["account_transfers exists with an unexpected relation kind"]
        return "MISSING", [f"table {name}"]
    checks = {
        "columns": all((
            _column(table, "id", "integer", False),
            _column(table, "source_account_id", "integer", False),
            _column(table, "destination_account_id", "integer", False),
            _column(table, "amount", "numeric(12,2)", False),
            _column(table, "transfer_date", "date", False),
            _column(table, "note", "text", True),
            _column(table, "created_at", "timestamp with time zone", False),
        )),
        "primary key": _constraint(table, "account_transfers_pkey", "p", ("primary key (id)",)),
        "source foreign key": _constraint(table, "account_transfers_source_account_id_fkey", "f", ("foreign key (source_account_id) references accounts(id)",)),
        "destination foreign key": _constraint(table, "account_transfers_destination_account_id_fkey", "f", ("foreign key (destination_account_id) references accounts(id)",)),
        "positive amount": _constraint(table, "account_transfers_amount_check", "c", ("amount >", "numeric", "0")),
        "distinct accounts": _constraint(table, "account_transfers_check", "c", ("check (source_account_id <> destination_account_id)",)),
        "source date index": _index(table, "idx_account_transfers_source_date", ("(source_account_id, transfer_date desc)",)),
        "destination date index": _index(table, "idx_account_transfers_destination_date", ("(destination_account_id, transfer_date desc)",)),
    }
    failed = [key for key, ok in checks.items() if not ok]
    exact_signature = signature_for("002", tables) == EXPECTED_SIGNATURES["002"]
    if not failed and exact_signature:
        return "APPLIED", []
    if not exact_signature:
        failed.append("account_transfers definition differs from the reviewed signature")
    present = sum(1 for key in ("primary key", "source date index", "destination date index") if checks[key])
    return "PARTIAL", failed


def _classify_003(tables: dict) -> tuple[str, list[str]]:
    accounts = tables.get("accounts")
    if not accounts:
        return "UNKNOWN", ["accounts table unavailable"]
    if not all((
        _column(accounts, "opening_balance", "numeric(12,2)", False),
        _column(accounts, "opening_debt", "numeric(12,2)", False),
    )):
        return "UNKNOWN", ["opening amount baseline is not established"]
    constraints = accounts.get("constraints", {})
    old_names = ("accounts_opening_balance_check", "accounts_opening_debt_check")
    base_check = constraints.get("accounts_check", {})
    canonical_base_definition = " ".join(base_check.get("definition", "").lower().split())
    canonical_base_check = base_check.get("type") == "c" and canonical_base_definition == (
        "check (type::text = 'credit_card'::text and credit_limit is not null "
        "and credit_limit > 0::numeric and opening_balance = 0::numeric "
        "or type::text <> 'credit_card'::text and credit_limit is null "
        "and opening_debt = 0::numeric)"
    )
    if not canonical_base_check:
        return "UNKNOWN", ["accounts baseline constraint is not established"]
    unexpected = [
        name for name, item in constraints.items()
        if item.get("type") == "c" and name not in (*old_names, "accounts_check")
        and re.search(r"opening_(balance|debt)", item.get("definition", ""), re.I)
    ]
    if unexpected:
        return "UNKNOWN", ["unreviewed opening-amount constraint: " + ", ".join(sorted(unexpected))]
    remaining = [name for name in old_names if name in constraints]
    if not remaining:
        return "APPLIED", []
    exact = all(_constraint(accounts, name, "c", (f"opening_{field} >= 0::numeric",))
                for name, field in zip(old_names, ("balance", "debt")))
    if len(remaining) == 2 and exact:
        return "MISSING", list(remaining)
    return "PARTIAL", list(remaining)


def _classify_004(tables: dict) -> tuple[str, list[str]]:
    accounts = tables.get("accounts")
    if not accounts or not all((
        _column(accounts, "id", "integer", False),
        _column(accounts, "type", "character varying(20)", False),
    )):
        return "UNKNOWN", ["accounts table unavailable"]
    column_present = "card_product_id" in accounts.get("columns", {})
    names = ("accounts_card_product_id_format", "accounts_card_product_id_not_cash")
    present = [name for name in names if name in accounts.get("constraints", {})]
    if not column_present and not present:
        return "MISSING", []
    ok = (
        _column(accounts, "card_product_id", "character varying(64)", True)
        and _constraint(accounts, names[0], "c", ("card_product_id is null", "~", "[a-z0-9]+(-[a-z0-9]+)*"))
        and _constraint(accounts, names[1], "c", ("<> 'cash'::text", "card_product_id is null"))
    )
    ok = ok and signature_for("004", tables) == EXPECTED_SIGNATURES["004"]
    return ("APPLIED", []) if ok else ("PARTIAL", ["accounts.card_product_id column/constraints differ"])


def _classify_005(tables: dict) -> tuple[str, list[str]]:
    required_tables = ("categories", "transactions")
    if any(name not in tables for name in required_tables):
        return "UNKNOWN", ["prior categories/transactions schema unavailable"]
    introduced = ("kakeibo_month_plans", "kakeibo_weekly_reviews")
    obj_present = []
    issues = []
    for name in introduced:
        if name in tables:
            obj_present.append(name)
        elif name in tables.get("__relation_kinds__", {}):
            issues.append(f"{name} exists with an unexpected relation kind")
    categories, transactions = tables["categories"], tables["transactions"]
    if not (_column(categories, "type", "character varying(10)", False)
            and _column(transactions, "transaction_date", "date", False)
            and _column(transactions, "amount", "numeric(12,2)", False)):
        return "UNKNOWN", ["prior categories/transactions definitions are not established"]
    col_a = "default_kakeibo_envelope" in categories.get("columns", {})
    col_b = "kakeibo_envelope" in transactions.get("columns", {})
    idx = "idx_transactions_kakeibo_date_envelope" in transactions.get("indexes", {})
    category_constraints = (
        "categories_default_kakeibo_envelope_allowed",
        "categories_default_kakeibo_envelope_expense_only",
    )
    transaction_constraints = ("transactions_kakeibo_envelope_allowed",)
    pieces = sum((
        col_a, col_b, idx, *(name in obj_present for name in introduced),
        *(name in tables.get("__relation_kinds__", {}) for name in introduced),
        *(name in categories.get("constraints", {}) for name in category_constraints),
        *(name in transactions.get("constraints", {}) for name in transaction_constraints),
    ))
    if pieces == 0:
        return "MISSING", []
    if not (_column(categories, "default_kakeibo_envelope", "character varying(12)", True)
            and _column(transactions, "kakeibo_envelope", "character varying(12)", True)):
        issues.append("envelope columns")
    allowed = ("needs", "wants", "culture", "unexpected")
    for table, constraint_name, field in (
        (categories, "categories_default_kakeibo_envelope_allowed", "default_kakeibo_envelope"),
        (transactions, "transactions_kakeibo_envelope_allowed", "kakeibo_envelope"),
    ):
        definition = table.get("constraints", {}).get(constraint_name, {}).get("definition", "").lower()
        if not definition or field not in definition or any(value not in definition for value in allowed):
            issues.append(constraint_name)
    expense = categories.get("constraints", {}).get("categories_default_kakeibo_envelope_expense_only", {}).get("definition", "").lower()
    if "= 'expense'::text" not in expense or "default_kakeibo_envelope is null" not in expense:
        issues.append("categories_default_kakeibo_envelope_expense_only")
    if not _index(transactions, "idx_transactions_kakeibo_date_envelope", ("(transaction_date, kakeibo_envelope)",)):
        issues.append("transaction envelope index")
    for table_name, columns, constraints in (
        ("kakeibo_month_plans", {
            "month": ("date", False), "planned_income": ("numeric(12,2)", False),
            "allocated_starting_funds": ("numeric(12,2)", False), "savings_target": ("numeric(12,2)", False),
            "prior_period_debt_reserve": ("numeric(12,2)", False), "needs_limit": ("numeric(12,2)", False),
            "wants_limit": ("numeric(12,2)", False), "culture_limit": ("numeric(12,2)", False),
            "unexpected_limit": ("numeric(12,2)", False), "monthly_intention": ("character varying(240)", True),
            "actual_saved_declared": ("numeric(12,2)", True), "review_actuals_snapshot": ("jsonb", True),
        }, ("kakeibo_month_plans_pkey", "kakeibo_month_plans_month_check",
            "kakeibo_month_plans_planned_income_check", "kakeibo_month_plans_allocated_starting_funds_check",
            "kakeibo_month_plans_savings_target_check", "kakeibo_month_plans_prior_period_debt_reserve_check",
            "kakeibo_month_plans_needs_limit_check", "kakeibo_month_plans_wants_limit_check",
            "kakeibo_month_plans_culture_limit_check", "kakeibo_month_plans_unexpected_limit_check",
            "kakeibo_month_plans_monthly_intention_check", "kakeibo_month_plans_actual_saved_declared_check",
            "kakeibo_month_plans_review_available_check", "kakeibo_month_plans_review_savings_check",
            "kakeibo_month_plans_review_change_check", "kakeibo_month_plans_review_appreciated_check",
            "kakeibo_month_plans_review_surprise_check", "kakeibo_month_plans_review_lesson_check",
            "kakeibo_month_plans_review_actuals_snapshot_check")),
        ("kakeibo_weekly_reviews", {
            "week_start": ("date", False), "surprise_note": ("text", True), "worthwhile_note": ("text", True),
            "next_week_intention": ("text", True),
        }, ("kakeibo_weekly_reviews_pkey", "kakeibo_weekly_reviews_week_start_check",
            "kakeibo_weekly_reviews_surprise_note_check", "kakeibo_weekly_reviews_worthwhile_note_check",
            "kakeibo_weekly_reviews_next_week_intention_check")),
    ):
        table = tables.get(table_name)
        if not table:
            issues.append(f"table {table_name}")
            continue
        for col, (typ, nullable) in columns.items():
            if not _column(table, col, typ, nullable):
                issues.append(f"{table_name}.{col}")
        for con in constraints:
            if con not in table.get("constraints", {}):
                issues.append(f"{table_name}.{con}")
    # Snapshot validation must be a CHECK which enforces object shape and all decimal-string totals.
    snapshot = tables.get("kakeibo_month_plans", {}).get("constraints", {}).get("kakeibo_month_plans_review_actuals_snapshot_check", {}).get("definition", "").lower()
    for fragment in ("jsonb_typeof", "actual_income", "total_expenses", "unclassified", "envelopes", "[0-9]"):
        if fragment not in snapshot:
            issues.append("snapshot JSON validation")
            break
    if pieces < 8:
        issues.append("one or more 005 objects absent")
    exact_signature = signature_for("005", tables) == EXPECTED_SIGNATURES["005"]
    if not exact_signature:
        issues.append("one or more category, transaction, month-plan, or weekly-review definitions differ from the reviewed signature")
    if issues:
        return ("PARTIAL" if pieces else "UNKNOWN", sorted(set(issues)))
    return "APPLIED", []


def _classify_006(tables: dict) -> tuple[str, list[str]]:
    plans = tables.get("kakeibo_month_plans")
    if not plans or _classify_005(tables)[0] != "APPLIED":
        return "UNKNOWN", ["005 plan table unavailable"]
    column = "plan_presence" in plans.get("columns", {})
    constraint = "kakeibo_month_plans_plan_presence_check" in plans.get("constraints", {})
    comment = plans.get("comments", {}).get("plan_presence")
    if not column and not constraint and not comment:
        return "MISSING", []
    ok = (
        _column(plans, "plan_presence", "character varying(12)", True)
        and _constraint(plans, "kakeibo_month_plans_plan_presence_check", "c", ("saved", "not_saved"))
        and comment == "saved/not_saved is explicit; NULL means a pre-006 row whose plan intent is unknown."
        and signature_for("006", tables) == EXPECTED_SIGNATURES["006"]
    )
    return ("APPLIED", []) if ok else ("PARTIAL", ["kakeibo_month_plans.plan_presence column/check/comment differs"])


def classify(inventory: dict) -> dict:
    tables = _objects(inventory)
    tables["__relation_kinds__"] = inventory.get("relation_kinds", {})
    checks = (_classify_002, _classify_003, _classify_004, _classify_005, _classify_006)
    report = {}
    for number, check in zip(("002", "003", "004", "005", "006"), checks):
        try:
            state, issues = check(tables)
        except (KeyError, TypeError, AttributeError):
            state, issues = "UNKNOWN", ["catalog metadata incomplete or unreadable"]
        report[number] = {"status": state, "issues": issues}
    return report


def role_is_read_only(inventory: dict) -> tuple[bool, list[str]]:
    role = inventory.get("role_security")
    if not isinstance(role, dict):
        return False, ["role privilege metadata unavailable"]
    problems = []
    for key in ("superuser", "create_database", "create_role", "replication", "inherit",
                "schema_create", "database_create", "database_temp", "owns_database", "owns_schema", "has_role_memberships",
                "owns_target_objects", "sequence_privileges"):
        if role.get(key) is not False:
            problems.append(key)
    privileges = role.get("table_privileges")
    if not isinstance(privileges, dict):
        problems.append("table privileges unavailable")
    else:
        for table_name, table_grants in privileges.items():
            for privilege in ("select", "insert", "update", "delete", "truncate", "references", "trigger"):
                if not isinstance(table_grants, dict) or table_grants.get(privilege) is not False:
                    problems.append(f"{table_name}.{privilege}")
    return not problems, problems


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("inventory", type=Path)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--run-id", default="UNKNOWN")
    parser.add_argument("--commit", default="UNKNOWN")
    parser.add_argument("--expected-database", default="monikey_dev")
    parser.add_argument("--unavailable", help="Fixed non-sensitive reason that no catalog inventory was obtained")
    args = parser.parse_args()
    try:
        if args.unavailable:
            inventory = {"database": args.expected_database, "server_version": "UNKNOWN", "tables": {}}
            results = {number: {"status": "UNKNOWN", "issues": [args.unavailable]}
                       for number in ("002", "003", "004", "005", "006")}
        else:
            inventory = json.loads(args.inventory.read_text())
            if inventory.get("database") != args.expected_database:
                raise ValueError("database target mismatch")
            version = inventory.get("server_version", "")
            if not isinstance(version, str) or not version.startswith("17."):
                results = {number: {"status": "UNKNOWN", "issues": ["PostgreSQL 17 signature baseline required"]}
                           for number in ("002", "003", "004", "005", "006")}
            else:
                results = classify(inventory)
    except (OSError, json.JSONDecodeError, ValueError) as exc:
        print(f"Schema inventory unavailable: {type(exc).__name__}", file=sys.stderr)
        return 2
    role_safe, role_issues = role_is_read_only(inventory)
    blocked = (not role_safe) or any(item["status"] in {"PARTIAL", "UNKNOWN"} for item in results.values())
    report = {
        "inspection": "READ ONLY",
        "timestamp_utc": datetime.now(timezone.utc).isoformat(),
        "workflow_run_id": args.run_id,
        "workflow_commit": args.commit,
        "expected_target": {"namespace": "monikey", "pod": "postgres-0", "database": args.expected_database},
        "database": inventory.get("database", "UNKNOWN"),
        "server_version": inventory.get("server_version", "UNKNOWN"),
        "financial_rows_inspected": 0,
        "schema_modifications_executed": 0,
        "migrations": results,
        "inspection_limitations": [
            issue for result in results.values() for issue in result["issues"]
            if issue == "PostgreSQL 17 signature baseline required"
        ],
        "database_role": {"catalog_only_check": "PASS" if role_safe else "FAIL", "issues": role_issues},
        "signature_comparison": {
            number: {
                "actual_sha256": signature_for(number, inventory.get("tables", {})),
                "reviewed_sha256": EXPECTED_SIGNATURES[number],
                "matches_reviewed_pg17_signature": signature_for(number, inventory.get("tables", {})) == EXPECTED_SIGNATURES[number],
            }
            for number in ("002", "004", "005", "006")
        },
        "verdict": "REVIEW REQUIRED" if blocked else "INVENTORY COMPLETE; NOT MIGRATION AUTHORIZATION",
    }
    args.output.write_text(json.dumps(report, indent=2, sort_keys=True) + "\n")
    print(f"Database: {report['database']}; PostgreSQL: {report['server_version']}")
    for number, result in results.items():
        print(f"Migration {number}: {result['status']}")
    print(f"Database role: {'catalog-only' if role_safe else 'privileges not verified'}")
    print("Financial rows inspected: 0")
    print("Schema modifications executed: 0")
    print(f"Verdict: {report['verdict']}")
    return 1 if blocked else 0


if __name__ == "__main__":
    raise SystemExit(main())
